meta={'cheer up': {'kind': 'Phrasal verb', 'spanish': 'Animarse / animar a alguien'}, 'calm down': {'kind': 'Phrasal verb', 'spanish': 'Calmarse'}, 'open up': {'kind': 'Phrasal verb', 'spanish': 'Abrirse y hablar de los sentimientos'}, 'fit in': {'kind': 'Phrasal verb', 'spanish': 'Encajar / sentirse integrado'}, 'get along with': {'kind': 'Phrasal verb', 'spanish': 'Llevarse bien con'}, 'reach out to': {'kind': 'Phrasal verb', 'spanish': 'Contactar para ofrecer o pedir ayuda'}, 'stand up for': {'kind': 'Phrasal verb', 'spanish': 'Defender / apoyar'}, 'look up to': {'kind': 'Phrasal verb', 'spanish': 'Admirar / respetar'}, 'break the ice': {'kind': 'Idiom', 'spanish': 'Romper el hielo'}, 'feel under the weather': {'kind': 'Idiom', 'spanish': 'Sentirse indispuesto / un poco enfermo'}, 'be on cloud nine': {'kind': 'Idiom', 'spanish': 'Estar feliz de la vida'}, 'have a heart of gold': {'kind': 'Idiom', 'spanish': 'Tener un corazón de oro'}}
